insert into public.investors (uuid, name, investor_type, investor_types, record_type, tagline, about, website, linkedin, image, dealroom_url, hq_city, hq_country, lat, lon, cheque_min, cheque_max, cheque_currency, preferred_round, stages, stage_mix, sectors, last_round_date, investments_count, london_rounds_since_2024) values
('729f14eb-ed32-42b9-9af8-873fce4b4f88', 'Octopus Ventures', 'venture_capital', 'venture_capital', 'organization', 'Multi-stage European venture capital investor backing pioneers in the areas of health, money and industry', 'Octopus Ventures is a London-based venture capital investor and part of Octopus Investments, within Octopus Group. It invests in the people, ideas and industries it believes will change the world, focusing on three areas: building a more sustainable planet, empowering people and revitalising healthcare. Its sector teams cover B2B Software, Bio, Climate, Consumer, Deep Tech, Fintech and Health. A dedicated Portfolio People + Talent team supports portfolio companies, and a twice-yearly mentorship programme matches portfolio founders and senior leaders with experienced executives and operators from its network.', 'https://octopusventures.com', 'https://www.linkedin.com/company/octopus-ventures', 'https://storage.googleapis.com/dealroom-images-production/2024/07/11/bdcc116a4fa7059d16000d13007f08c4.jpg', 'https://app.dealroom.co/investors/octopus_ventures', 'London', 'United Kingdom', 51.517597, -0.1088286, 189394, 18939386, 'GBP', 'SERIES A', 'SERIES A|Seed|Series B|Series A|Series C', 'Seed:8|Series B:5|Series A:3|Series C:2', 'Techstars 501 Investors|Life sciences', '2026-10', 536, 49),
('81bca5ea-1155-4e7e-93ef-0149c565446c', 'SFC Capital', 'venture_capital', 'venture_capital|angel_fund', 'organization', 'Seed investor providing capital and support to early-stage British startups', null, 'https://sfccapital.com', 'https://www.linkedin.com/company/startupfundingclub', 'https://storage.googleapis.com/dealroom-images-production/2021/01/19/afbde1b5c2a8b68178e2781a8a174cbf.jpg', 'https://app.dealroom.co/investors/sfc_capital', 'London', 'United Kingdom', 51.50735, -0.1277583, null, null, 'GBP', 'SEED', 'SEED|Seed|Pre-Seed|Other', 'Seed:8|Pre-Seed:7|Other:1', 'Life sciences', '2026-10', 487, 84),
('71a0684c-8b3b-4349-af83-7e71bc0f5d25', 'SOSV', 'venture_capital', 'venture_capital', 'organization', 'SOSV is a global venture capital firm that operates early stage startup development programs', 'SOSV is a global venture capital firm investing in deep tech startups at the pre-seed stage, positioning itself as "The First Check in Deep Tech". Through its flagship programs HAX (hard tech, robotics and industrial innovation, headquartered in Newark, NJ) and IndieBio (life sciences and synthetic biology, in New York and San Francisco), SOSV backs founders working on human and planetary health with capital, hands-on support and lab facilities. SOSV has invested in more than 800 portfolio companies, which together raised about US$7.5B between 2021 and 2025, and operates from offices across the US, Europe and Asia.', 'https://sosv.com', 'https://www.linkedin.com/company/sosvvc', 'https://storage.googleapis.com/dealroom-images-production/2020/04/04/346f4d4ed64128f84c846d01bcff615e.jpg', 'https://app.dealroom.co/investors/sosv', 'Princeton', 'United States', 40.350754, -74.65629, 0, 1893939, 'GBP', 'SEED', 'SEED|Seed|Bridge|Series A', 'Seed:7|Bridge:2|Series A:2', 'Life sciences|Consumer Goods', '2026-10', 2175, 11),
('9c3c8279-3e29-4b58-8f10-fcb0730acb26', 'Entrepreneurs First', 'venture_capital', 'venture_capital|corporate', 'organization', 'Bringing together exceptional people to meet their co-founders and build global startups', null, 'https://joinef.com', 'https://www.linkedin.com/company/entrepreneurs-first/', 'https://storage.googleapis.com/dealroom-images-production/2026/06/27/dec22741fccb873413d08fc1f7786a24.png', 'https://app.dealroom.co/investors/entrepreneurs_first', 'London', 'United Kingdom', 51.495403, -0.0614486, 0, 151515, 'GBP', 'SEED', 'SEED|Seed|Pre-Seed|Series C', 'Seed:7|Pre-Seed:1|Series C:1', 'Business Intelligence|Social Entrepreneurship|Investing in Startups|Life sciences', '2026-10', 480, 28),
('a3971b56-d04d-485d-a3a6-25e7ee716e71', 'Eka Ventures', 'venture_capital', 'venture_capital', 'organization', 'Eka invests in category-defining technology companies that positively shape the world, making it more sustainable, healthy and inclusive', 'We work with founders building category-defining consumer technology companies that positively shape the world, making it more sustainable, healthy and inclusive.', 'https://ekavc.com', 'https://www.linkedin.com/company/eka-ventures/', 'https://storage.googleapis.com/dealroom-images-production/2024/07/31/25ca723097ecbf52e21b89aba6237322.png', 'https://app.dealroom.co/investors/eka_ventures', 'London', 'United Kingdom', 51.49423, -0.1916216, null, null, 'GBP', 'SEED', 'SEED|Seed|Series A', 'Seed:7|Series A:2', 'B Corp|Life sciences', '2026-10', 36, 13),
('512e84fd-23e5-4c8a-b8aa-8656dc9d4212', 'Calm/Storm Ventures', 'venture_capital', 'venture_capital', 'organization', 'Early-stage venture capital firm focused on digital health and wellbeing startups', 'Calm/Storm is an exclusive founder network and boutique venture capital firm. We focus on talents, not industries. We believe in lifelong learning & personal growth, empowering entrepreneurs with unique access to successful founders. We are a fund built by founders for founders.', 'https://calmstorm.vc', 'https://www.linkedin.com/company/calmstorm/', 'https://storage.googleapis.com/dealroom-images-production/2026/10/26/0674c440bd6355ca1b6e555de89127ea.png', 'https://app.dealroom.co/investors/calm_storm_ventures', 'Vienna', 'Austria', 48.189606, 16.375446, null, null, 'GBP', 'SEED', 'SEED|Seed|Pre-Seed|Series A', 'Seed:6|Pre-Seed:1|Series A:1', 'Life sciences', '2026-10', 100, 8),
('7e222100-04b4-41ae-8132-be619273cc87', 'Exceptional Ventures', 'venture_capital', 'venture_capital', 'organization', 'Early-stage VC firm investing in startups that enhance health, happiness, and longevity', 'At Exceptional Ventures, our motto is Believing in Believers. We believe that innovative businesses can make the world a better place, and we believe in entrepreneurs that feel the same. It is our mission to support them with our expertise and capital, and to help them build a better future. We focus on businesses that are helping people live healthier, happier, longer lives. Our portfolio ranges from sustainable consumer products to applications focused on mental and physical health, and on the future of foods. We have extensive experience and networks across Europe that we have built while running and investing in some of Europe’s most successful businesses. We have over 50 years of combined expertise across the sectors of focus and a portfolio of over 160 startups. We are uniquely able to access the most talented entrepreneurs building the most progressive companies and are building a portfolio of 40 exceptional businesses in our first fund. We offer extensive support to companies early in their journeys with our capital, network, and advice. By bringing together passionate investors and world-class entrepreneurs, our mission is to improve the length and quality of human lives, while helping to build a sustainable planetary ecosystem.', 'https://exceptional.ventures', 'https://www.linkedin.com/company/exceptional-ventures/', 'https://storage.googleapis.com/dealroom-images-production/2026/10/27/7874ac1291324e6a3f08281a5b410d82.png', 'https://app.dealroom.co/investors/exceptional_ventures', 'London', 'United Kingdom', 51.52077, -0.1221087, null, null, 'GBP', 'SEED', 'SEED|Seed|Pre-Seed|Series A', 'Seed:6|Pre-Seed:1|Series A:1', 'Life sciences', '2026-09', 36, 9),
('69f5423b-12cf-4ab4-b41d-03e0bc1351f0', 'Plug and Play', 'venture_capital', 'venture_capital', 'organization', 'Global innovation platform connecting startups with corporations', 'Plug and Play is a global innovation platform headquartered in Sunnyvale, California (Silicon Valley), founded in 2006 by Saeed Amidi. It connects startups, corporations, venture capital firms, universities and government agencies through industry-focused accelerator and corporate innovation programs in more than 60 locations worldwide. Its venture arm, Plug and Play Ventures, invests from pre-seed to Series A (and at later stages where there is a fit), making around 250 investments per year, and counts more than 30 unicorns in its portfolio. It also manages dedicated vehicles such as the Fintech & AI, Supply Chain, Sustainability, Future Commerce and Japan funds.', 'https://plugandplaytechcenter.com', 'https://www.linkedin.com/company/plug-and-play-tech-center/', 'https://storage.googleapis.com/dealroom-images-production/2020/04/07/d3d5a37cbc8f2d150f93e38c17e74161.png', 'https://app.dealroom.co/investors/plug_and_play_1', 'Sunnyvale', 'United States', 37.38354, -122.01319, null, null, 'GBP', 'SEED', 'SEED|Seed|Bridge', 'Seed:6|Bridge:1', 'Life sciences', '2026-10', 1981, 7),
('a9d89ae3-22df-49b8-9fb6-57ad8701973d', 'Seedcamp', 'venture_capital', 'venture_capital', 'organization', 'Europe''s seed fund, investing early in world-class founders attacking large, global markets and solving real problems using technology', 'Seedcamp is a London-based early-stage venture capital firm founded in 2007 by Reshma Sohoni and Saul Klein. It invests at pre-seed and seed in European founders building software businesses for global markets, typically leading or co-leading first institutional rounds of up to $1M and following on up to Series B. Sector-agnostic, it focuses on areas such as AI, fintech, cybersecurity, developer and open-source tools, and health tech, and generally avoids capital-intensive models. Seedcamp has backed more than 460 companies, including UiPath, Wise, Revolut, Pleo, Hopin, Grover, Viz.ai, wefox, Sorare and Synthesia. In 2026 it raised $320M of new capital across Seedcamp Fund VII and Seedcamp Nation II, after closing its EUR 166M Fund VI in 2023; LPs include LGT, HarbourVest, Reference Capital and Legal & General. Beyond capital, it supports founders through its network of alumni founders, angels and the Seedcamp Expert Collective.', 'https://seedcamp.com', 'https://www.linkedin.com/company/seedcamp_2/', 'https://storage.googleapis.com/dealroom-images-production/2024/12/18/a37dab9adddf1a499006e4b4f8e48ea9.png', 'https://app.dealroom.co/investors/seedcamp', 'London', 'United Kingdom', 51.51366, -0.13288116, null, null, 'GBP', 'SEED', 'SEED|Seed|Series A|Series B', 'Seed:5|Series A:1|Series B:1', 'Investing|Platform|Life sciences', '2026-10', 697, 41),
('2367c5fb-2d0f-493e-b13e-5f5196fa1665', 'Sofinnova Partners', 'venture_capital', 'venture_capital', 'organization', 'Leading European venture capital firm specialized in Life Sciences, often lead role in round A financings', null, 'https://sofinnovapartners.com', 'https://www.linkedin.com/company/sofinnova-partners', 'https://storage.googleapis.com/dealroom-images-production/2022/01/10/d150f5b8ff300fda7aa138df6badb46c.jpg', 'https://app.dealroom.co/investors/sofinnova_partners', 'Paris', 'France', 48.872597, 2.3358002, 5681816, 15151509, 'GBP', 'SERIES A', 'SERIES A|Series A|Series B|Seed', 'Series A:4|Series B:2|Seed:1', 'Life sciences|Lead Generation|Biotechnology|Medical & Healthcare|Techstars 501 Investors', '2026-10', 378, 7),
('b33be174-c396-4a07-8448-a3d4ab5fba92', 'Atomico', 'venture_capital', 'venture_capital', 'organization', 'European venture capital firm backing ambitious tech founders from seed to growth stage', 'Atomico is a European venture capital firm founded in 2006 by Niklas Zennström, the co-founder of Skype. Headquartered in London, with offices in Paris, Berlin, Stockholm and Luxembourg, it invests in ambitious technology companies across Europe from seed and Series A through to growth stage, and supports founders with an operational team covering talent, go-to-market, marketing and policy. In September 2024 Atomico closed $1.24B across two funds: Atomico Venture VI ($485M) for early-stage deals and Atomico Growth VI ($754M) for growth rounds. Earlier funds include Atomico V ($820M, 2020) and Atomico IV ($765M, 2017). Its portfolio has included Klarna, Supercell, Graphcore, Lilium, Wolt, DeepL, Factorial, Neko Health, Raycast and The Exploration Company. Atomico also publishes the annual State of European Tech report.', 'https://atomico.com', 'https://www.linkedin.com/company/atomico/', 'https://storage.googleapis.com/dealroom-images-production/2026/04/30/48ba998182e35420447d411a3f529c1c.png', 'https://app.dealroom.co/investors/atomico', 'London', 'United Kingdom', 51.51833, -0.1356167, 1, 56818159, 'GBP', 'SERIES A', 'SERIES A|Seed|Series B|Series A', 'Seed:4|Series B:2|Series A:1', 'Automotive|Aerospace|PaaS|Analytics|Music|Consumer Electronics|Apparel|SaaS|Social|Social Media|Messaging|Security|On-Demand|Biotechnology|Techstars 501 Investors|Wellness / Beauty|Medical / Healthcare|Insurance|Wearable|Life sciences', '2026-10', 292, 21),
('4c33aa9d-c7ff-4489-9530-847dea9c8976', 'Redalpine', 'venture_capital', 'venture_capital', 'organization', 'Redalpine is leading multi-stage venture capital firm investing in the connection of software & science across Europe since 2006', null, 'https://redalpine.com', 'https://www.linkedin.com/company/redalpine-venture-partners-ag', 'https://storage.googleapis.com/dealroom-images-production/2025/02/19/495dcec3360beb204c49dd54f0c93b5a.jpeg', 'https://app.dealroom.co/investors/redalpine', 'Zurich', 'Switzerland', 47.390297, 8.514788, 0, 1893939, 'GBP', 'SEED', 'SEED|Seed|Series A|Series B|Series C', 'Seed:3|Series A:2|Series B:1|Series C:1', 'Life sciences|Telecommunications|Health|Biotechnology|Medical & Healthcare|Techstars 501 Investors|Web Design|Life Science', '2026-10', 189, 7),
('90827cb2-fec8-49fe-b194-e742c7b6f8ad', 'Oxford Science Enterprises', 'venture_capital', 'venture_capital', 'organization', 'Turning Oxford''s world-leading science into world-changing companies', 'We are Oxford Science Enterprises, the Science Business Builder. We want to help solve the world’s toughest problems for more people, in more places, faster. • Enabling people to lead longer, healthier lives • Protecting the future of our planet • Creating a safe, secure world • Accelerating the pace of positive change We do this by transforming world-leading science into world-changing businesses, partnering the best scientists, from the world’s best university with the best business brains. We grow our companies with care and expertise; in a way that is systematic and scalable. We invest for real-world impact, not only financial returns. And we re-invest proceeds back into the next generation of original research and world changing businesses. Our enterprises address problems that affect people in life-changing ways: their health; the availability of food; the survival of the planet. Since 2015, we have received an automatic stake in all Oxford University science spinouts; more than 100 businesses, founded by over 200 of Oxford’s leading academics – and we have taken a leading role in creating and building over 60 of these; adding +55,000 sq ft of lab & start-up space to support them. Today our businesses are worth over £2bn and have created +1,500 jobs. Our vision is a world where the best scientists and brightest business minds combine to solve our biggest challenges at unprecedented speed. We’re working to create that world, and we’re doing it in a way that we’ll be pro…', 'https://oxfordscienceenterprises.com', 'https://www.linkedin.com/company/oxford-science-enterprises/', 'https://storage.googleapis.com/dealroom-images-production/2025/11/19/84eaa2209e7c8ef54a0164e51717c76b.jpeg', 'https://app.dealroom.co/investors/oxford_science_enterprises', 'Oxford', 'United Kingdom', 51.76102, -1.2617496, null, null, 'GBP', 'SEED', 'SEED|Seed|Series A', 'Seed:4|Series A:3', 'Life sciences|Analytics|Consumer Electronics|Data Analytics|Developer Tools', '2026-10', 189, 7),
('a50b7737-3df9-4693-a9b5-4d48264bfb26', 'Hoxton Ventures', 'venture_capital', 'venture_capital', 'organization', 'Early stage European venture capital firm', 'Hoxton Ventures helps entrepreneurs invent new industries and disrupt existing ones.', 'https://hoxtonventures.com', 'https://www.linkedin.com/company/hoxton-ventures', 'https://storage.googleapis.com/dealroom-images-production/2024/04/15/018b875174a57bf4cd331976fd117a96.png', 'https://app.dealroom.co/investors/hoxton_ventures', 'London', 'United Kingdom', 51.516994, -0.1262665, 378788, 3787877, 'GBP', 'SEED', 'SEED|Seed|Series A', 'Seed:4|Series A:3', 'Techstars 501 Investors|Life sciences', '2026-09', 120, 12),
('311bf922-e16f-4397-9259-89c2f4ed3107', 'Balderton Capital', 'venture_capital', 'venture_capital', 'organization', 'Venture firm with a multi-stage approach and over twenty years of expertise in aiding European founders from the initial seed stage through to IPO', 'Balderton is Europe''s leading venture firm focused exclusively on backing European-founded tech companies. In the 26 years since its founding (as Benchmark Capital Europe, in 2000), Balderton has worked with hundreds of European founders and has raised more than $5.7bn across 12 funds. It takes a multi-stage approach, backing founders from seed through to IPO, most recently with the $615m Early Stage Fund IX and the $685m Growth Fund II announced in August 2024. Beyond capital, Balderton supports portfolio founders and teams through its talent, legal, finance and founder-wellbeing programmes, and through a bench of Executives in Residence.', 'https://balderton.com', 'https://www.linkedin.com/company/balderton/', 'https://storage.googleapis.com/dealroom-images-production/2024/02/16/3b67841b3ad758aba42140c782b2d474.jpeg', 'https://app.dealroom.co/investors/balderton_capital', 'London', 'United Kingdom', 51.530197, -0.1171251, 1, 15151509, 'GBP', 'SERIES A', 'SERIES A|Seed|Series A|Series B', 'Seed:2|Series A:2|Series B:2', 'Automotive|Aerospace|PaaS|Analytics|Music|Consumer Electronics|Apparel|Retail|SaaS|Social|Social Media|Messaging|Security|Biotechnology|Media Production|Techstars 501 Investors|Wellness / Beauty|Medical / Healthcare|Insurance|Wearable|Life sciences', '2026-10', 580, 26),
('7d3c9943-e634-4481-848a-80bcf452c848', 'LocalGlobe', 'venture_capital', 'venture_capital', 'organization', 'Phoenix Court''s pre-seed and seed fund, backing founders across the UK and Europe', 'LocalGlobe is the pre-seed and seed-stage venture fund of Phoenix Court (formerly Phoenix Court Group), the London-based multi-stage investment business co-founded by Saul and Robin Klein. A sector-generalist early-stage fund, it is where most Phoenix Court relationships begin, backing founders across the UK and Europe from their first rounds. Its sister funds are Latitude (early growth, Series B and later), Solar (scale-up) and Basecamp (emerging managers). Portfolio companies include Mistral AI, Tide, Cleo, Citymapper, Zoopla, Wise and Motorway. The team is based at Phoenix Court, 2 Brill Place, King''s Cross, London.', 'https://localglobe.vc', 'https://www.linkedin.com/company/localglobe/', 'https://storage.googleapis.com/dealroom-images-production/2024/09/24/dec64f3b8b5ca880339c57d312574ec0.jpg', 'https://app.dealroom.co/investors/localglobe', 'London', 'United Kingdom', 51.53206, -0.1287681, 378788, 1893939, 'GBP', 'SEED', 'SEED|Seed|Series A|Series B', 'Seed:4|Series A:1|Series B:1', 'Techstars 501 Investors|Life sciences', '2026-10', 482, 27),
('a12e64a9-9f71-4d56-b54c-a804f49158da', 'THENA Capital', 'venture_capital', 'venture_capital', 'organization', 'Early Stage MedTech Venture Capital', null, 'https://thenacapital.com', 'https://www.linkedin.com/company/thena-capital/', 'https://storage.googleapis.com/dealroom-images-production/2024/03/08/98c29bffede12ca7b4f444c85e332f57.png', 'https://app.dealroom.co/investors/thena_capital', 'London', 'United Kingdom', 51.507446, -0.1277653, null, null, 'GBP', 'SEED', 'SEED|Seed', 'Seed:6', 'Life sciences', '2026-07', 4, 6),
('9ebd6f16-d5c8-4f7a-be4d-ae37d0d145f1', 'General Catalyst', 'venture_capital', 'venture_capital', 'organization', 'A global investment and transformation company that partners with the world''s most ambitious entrepreneurs to drive resilience and applied AI', 'General Catalyst is a global investment and transformation company founded in 2000 in Cambridge, MA by Joel Cutler and David Fialkow. Led by CEO Hemant Taneja, it backs companies from seed to growth (Ignition, Endurance, Health Assurance and Creation strategies, plus the Customer Value Fund) with a focus on applied AI, healthcare, defense, industrials, energy and fintech. Offices in Cambridge, San Francisco, New York, Washington DC, London, Berlin and Bengaluru. Fund XII (2024) raised ~$8B.', 'https://generalcatalyst.com', 'https://www.linkedin.com/company/general-catalyst/', 'https://storage.googleapis.com/dealroom-images-production/2026/04/30/6d6bf31b33a51d94300cbd6945c393a0.png', 'https://app.dealroom.co/investors/general_catalyst_partners', 'Cambridge', 'United States', 42.372658, -71.12341, 18939386, 75757545, 'GBP', 'SERIES A', 'SERIES A|Seed|Series A|Series B', 'Seed:3|Series A:1|Series B:1', 'Life sciences|Equity Research|Techstars 501 Investors|Capital Market', '2026-10', 1802, 5),
('1865c5d6-c444-4cd5-a15e-4353b31448a6', 'Khosla Ventures', 'venture_capital', 'venture_capital', 'organization', 'Founded by Vinod Khosla, co-founder of Sun Microsystems, to support entrepreneurs across diverse sectors: AI, climate, sustainability, fintech, health tech, and frontier technology', null, 'https://khoslaventures.com', 'https://www.linkedin.com/company/khosla-ventures/', 'https://storage.googleapis.com/dealroom-images-production/2026/05/24/9e46d927e526adfe6eaeb2c5eee08b9e.png', 'https://app.dealroom.co/investors/khosla_ventures', 'Menlo Park', 'United States', 37.425102, -122.19359, 11363632, 37878773, 'GBP', 'SERIES A', 'SERIES A|Series B|Seed|Series A', 'Series B:3|Seed:1|Series A:1', 'Life sciences', '2026-10', 1650, 5),
('9b68ddd9-f64c-4fb5-a918-ebcb12792423', '8VC', 'venture_capital', 'venture_capital', 'organization', 'Early-stage venture capital for transformative technology companies', '8VC is a venture capital firm based in Austin, Texas, that builds and invests in technology and life sciences companies. Founded in 2015 by Joe Lonsdale, Jake Medwell, Drew Oetting, and Alex Kolicich, the firm manages over $6 billion in committed capital and invests across all stages, from seed to growth. The firm''s stated mission is to "fix a broken world" by partnering with entrepreneurs to create solutions for complex challenges. The firm emerged from the breakup of Formation 8, a prior venture firm co-founded by Lonsdale. Lonsdale, a co-founder of Palantir Technologies, Addepar, and OpenGov, relocated 8VC from San Francisco to Austin in 2020. His background includes an internship at PayPal and work at Clarium Capital, a hedge fund managed by his mentor, Peter Thiel. The firm''s investment philosophy is not momentum-driven but focuses on identifying technological changes that enable new business possibilities. 8VC actively incubates companies through its "8VC Build" program, where it leverages its network and entrepreneurial experience to launch new ventures that address identified market gaps. 8VC''s investment strategy is diversified across several key sectors. Approximately half of its investments are in software, including enterprise applications, and IT infrastructure. Other major focus areas are life sciences, biotechnology, healthcare, defense, and logistics. The firm primarily makes early-stage investments, often in Series A rounds, with typical check sizes ranging …', 'https://8vc.com', 'https://www.linkedin.com/company/8vc/', 'https://storage.googleapis.com/dealroom-images-production/2026/10/28/fcc34186ed540e342187a058200d1e17.png', 'https://app.dealroom.co/investors/8vc', 'Austin', 'United States', 30.254623, -97.747475, 189394, 38, 'GBP', 'SEED', 'SEED|Series A|Other|Seed', 'Series A:3|Other:1|Seed:1', 'Life sciences|Aerospace|PaaS|Analytics|SaaS|Social Media|Messaging|On-Demand|Wellness / Beauty', '2026-10', 625, 5),
('32855b78-743e-4755-9609-2b4201b6634f', 'Mercia Asset Management', 'venture_capital', 'venture_capital|private_equity', 'organization', 'Provides investment growth capital and support services', 'Mercia Asset Management PLC is a UK proactive, specialist asset manager focused on supporting regional businesses to scale. Through its subsidiaries and funds, Mercia provides venture capital, business loans and private equity ranging from around £100k to £10m, backing ambitious UK founders and SMEs that typically seek up to £10 million of capital. Its investment platforms include Mercia Ventures (venture capital up to £10m), Mercia Business Loans (business loans up to £2m), Frontier Development Capital / FDC (growth capital up to £8m) and Mercia PE (private equity up to £10m). Headquartered in the UK and listed on AIM, Mercia manages a mix of proprietary balance-sheet capital, third-party funds and the Northern VCTs, aiming to be a responsible, long-term investment partner that pledges more than just capital.', 'https://mercia.co.uk', 'https://www.linkedin.com/company/mercia-asset-management/', 'https://storage.googleapis.com/dealroom-images-production/2026/07/28/f273ef61f851ad6b30fc486011c0a0be.jpeg', 'https://app.dealroom.co/investors/mercia_fund_management', 'Henley-in-Arden', 'United Kingdom', 52.29228, -1.7801276, 75758, 1893939, 'GBP', 'SERIES A', 'SERIES A|Seed|Series A|Series B|Series C', 'Seed:2|Series A:1|Series B:1|Series C:1', 'Life sciences|Medical Technology|Life Science', '2026-10', 479, 5),
('64ff6eeb-18b1-4c12-87c7-f1f11d1a4117', 'Future Planet Capital', 'venture_capital', 'private_equity|venture_capital', 'organization', 'impact-led venture capital firm built to back innovative companies from the world’s top universities and research ecosystems.', 'Future Planet is a global venture capital and impact investor. Through a unique series of partnerships and relationships around the world''s top universities, we provide venture and growth investment to entrepreneurs and businesses profitably solving the world''s greatest challenges in Climate Change, Education, Health, Sustainable Growth & Security. We''ve established a network that affords an unrivalled level of access to technology and life science firms that emerge from academic institutions and the "clusters of innovation" that surround them. Our mission is not simply to deliver excellent returns but to create a lasting impact: by connecting the world''s largest investors with its best minds, we believe we can address the greatest challenges that humanity faces today. The Future Planet Fund has been designed in close conjunction with sophisticated investors in order to provide multi-stage access to start-ups, spin-outs and growing companies, at a scale large enough to suit major sovereign wealth funds and similar institutions.', 'https://futureplanetcapital.com', 'https://www.linkedin.com/company/future-planet-capital', 'https://storage.googleapis.com/dealroom-images-production/2020/11/15/a2082f0e22434d4415f752529e154122.jpg', 'https://app.dealroom.co/investors/futureplanetcapital', 'London', 'United Kingdom', 51.50643, -0.12721, null, null, 'GBP', 'SEED', 'SEED|Seed', 'Seed:5', 'Life sciences', '2026-09', 309, 9),
('bb487d35-cbed-419f-ac10-4aca90764fd8', 'MMC Ventures', 'venture_capital', 'venture_capital', 'organization', 'Backing transformative tech companies from the Seed and Series A stage', 'MMC invests growth equity in dynamic young companies in the UK. We back companies at an early stage and work in partnership with them to grow to substantial scale and profitability.', 'https://mmc.vc', 'https://www.linkedin.com/company/mmc-ventures/', 'https://storage.googleapis.com/dealroom-images-production/2020/06/22/972e8b03e08baca486fadf04dc2dbca8.jpg', 'https://app.dealroom.co/investors/mmc_ventures', 'London', 'United Kingdom', 51.507336, -0.12765, 757575, 7575755, 'GBP', 'SERIES A', 'SERIES A|Seed', 'Seed:5', 'B Corp|Life sciences', '2026-10', 231, 20),
('f7a455eb-2b38-4081-b017-ef42eb22148c', 'Firstminute Capital', 'venture_capital', 'venture_capital', 'organization', '$325m AUM seed fund backed by over 120 unicorn founders investing across Europe and the US', '$320m AUM seed fund backed by over 120 unicorn founders investing across Europe and the US. Founded in 2017 by Brent Hoberman and Spencer Crawley.', 'https://firstminute.capital', 'https://www.linkedin.com/company/firstminutecapital/', 'https://storage.googleapis.com/dealroom-images-production/2024/06/10/1a68a586907d5713a5f041e03612094b.png', 'https://app.dealroom.co/investors/firstminute_capital', 'London', 'United Kingdom', 51.513435, -0.1129236, null, null, 'GBP', 'SEED', 'SEED|Seed|Series A|Series B', 'Seed:2|Series A:2|Series B:1', 'Life sciences', '2026-10', 208, 22),
